/** Mint a TTS-scoped token (`aud:"tts"`) for `slug`, valid for
 *  {@link VIEW_TOKEN_TTL_MS}. It authorizes ONLY the /api/tts proxy — it is
 *  rejected by the data-endpoint guard — so a leaked token can do nothing but
 *  request speech (already length- + rate-capped). Least privilege for the
 *  standalone voice-nav tab, which receives it via URL fragment. */
export function mintTtsToken(slug: string, nowMs: number = Date.now()): { token: string; exp: number } | null {
  const key = getCurrentToken();
  if (key === null) return null;
  const exp = nowMs + VIEW_TOKEN_TTL_MS;
  const payload: ViewTokenPayload = { slug, caps: ["read"], exp, aud: "tts" };
  const payloadB64 = Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
  return { token: `${payloadB64}.${signPayload(payloadB64, key)}`, exp };
}

