/** Express middleware guarding the /api/tts proxy: require a valid token whose
 *  audience is `"tts"`. 401 (generic message) on any failure. The token carries
 *  no data capability — it authorizes speech synthesis and nothing else. */
export function requireTtsToken() {
  return function requireTtsTokenMiddleware(req: Request, res: Response, next: NextFunction): void {
    const header = req.headers.authorization;
    if (typeof header !== "string" || !header.startsWith(BEARER_PREFIX)) {
      unauthorized(res, "unauthorized");
      return;
