const APP_PATH = "/artifacts/html/2026/07/voice-nav.html";
const { token, dataUrl } = window.__MC_VIEW;

// Pre-mint a TTS-scoped token so the app tab can call /api/tts (OpenAI voice).
// It authorizes ONLY /api/tts (never this collection's data), 1 h TTL. We fetch
// it once on load and pass it to the opened tab via URL *fragment* (`#mcvt=`) —
// fragments are never sent to the server, are stripped from the Referer header,
// and the app strips it from its address bar immediately on load. If minting
// fails, the app simply falls back to the browser's Web Speech voice.
let ttsToken = null;
(async () => {
  try {
    const mintUrl = dataUrl.replace(/\/view-data(\?.*)?$/, "/tts-token");
    const res = await fetch(mintUrl, { method: "POST", headers: { Authorization: "Bearer " + token } });
    if (res.ok) ttsToken = (await res.json()).token || null;
  } catch (_) { /* fall back to Web Speech in the app */ }
})();

function appUrl(item){
  const base = new URL(APP_PATH, dataUrl).href;
  const params = new URLSearchParams();
  if(item){
    const q = (item.query && item.query.trim()) ? item.query.trim() : (item.name||"");
    if(q) params.set("to", q);
    if(item.mode==="徒歩") params.set("mode","walk");
  }
  const s = params.toString();
  let url = s ? base+"?"+s : base;
  if(ttsToken) url += "#mcvt=" + encodeURIComponent(ttsToken);
  return url;
}
function openApp(item){ window.open(appUrl(item), "_blank", "noopener"); }

