  ja: /(google|siri|kyoko|o-?ren|otoya|hattori|sayaka|nanami|ayumi|natural|neural|premium|enhanced)/i,
  en: /(google|siri|samantha|ava|allison|aria|jenny|guy|natural|neural|premium|enhanced|karen|serena|moira|tessa|nicky|joana|zoe|evan)/i
};
