  }
}
function stopNav(){
  S.navOn=false;
  if(S.watchId!=null){navigator.geolocation.clearWatch(S.watchId);S.watchId=null;}
  releaseWakeLock();
  $("banner").classList.remove("show");
  S.map.setTilt?.(0);
  botSay(T().navStop);
}

/* Screen Wake Lock — スマホを車載してナビ中に画面が消えるのを防ぐ。非対応環境や
   拒否時は黙って無視（ナビ機能自体には影響しない）。タブ復帰時に自動で取り直す。 */
let _wakeLock=null;
async function requestWakeLock(){
  try{ if("wakeLock" in navigator){ _wakeLock=await navigator.wakeLock.request("screen");
    _wakeLock.addEventListener?.("release",()=>{ _wakeLock=null; }); } }catch(e){ _wakeLock=null; }
}
function releaseWakeLock(){ try{ _wakeLock?.release?.(); }catch(e){} _wakeLock=null; }
document.addEventListener("visibilitychange",()=>{
  if(document.visibilityState==="visible" && S.navOn && !_wakeLock) requestWakeLock();
});

