import fs from "fs";

// --- key from .env (never printed) ---
let key = process.env.OPENAI_API_KEY || "";
if (!key && fs.existsSync(".env")) {
  const m = fs.readFileSync(".env", "utf8").match(/^OPENAI_API_KEY\s*=\s*(.+)$/m);
  if (m) key = m[1].trim().replace(/^['"]|['"]$/g, "");
}
if (!key) { console.error("no key"); process.exit(1); }

const URL = "https://api.openai.com/v1/chat/completions";
const MODEL = "gpt-4o-mini";

const SYS = "あなたはカーナビMulmoNaviの音声アシスタント。運転中のドライバーと話す相棒。返答はcontext.langの言語。ナビ操作は道具(tool)を呼ぶ。雑談は2〜3文で会話。記号・絵文字禁止。";

const TOOLS = [
  { type:"function", function:{ name:"navigate", description:"目的地を設定してルート検索を開始", parameters:{ type:"object", properties:{ destination:{type:"string"}, avoidHighways:{type:"boolean"} }, required:["destination"] } } },
  { type:"function", function:{ name:"change_route", description:"現在のルート条件を変更(高速回避/経由地追加)。ナビは終了しない", parameters:{ type:"object", properties:{ avoidHighways:{type:"boolean"}, addWaypoint:{type:"string"} } } } },
  { type:"function", function:{ name:"get_status", description:"現在地/残距離/ETA/走行モードを取得", parameters:{ type:"object", properties:{} } } },
  { type:"function", function:{ name:"search_poi", description:"周辺またはルート沿いのPOI検索", parameters:{ type:"object", properties:{ query:{type:"string"}, nearRoute:{type:"boolean"} }, required:["query"] } } },
  { type:"function", function:{ name:"control", description:"ナビ操作", parameters:{ type:"object", properties:{ action:{type:"string", enum:["start","stop","repeat","mute"] } }, required:["action"] } } },
  { type:"function", function:{ name:"remember", description:"好み・事実を保存", parameters:{ type:"object", properties:{ fact:{type:"string"} }, required:["fact"] } } },
  { type:"function", function:{ name:"recall", description:"保存済みの好み・事実を想起", parameters:{ type:"object", properties:{ topic:{type:"string"} }, required:["topic"] } } },
];

const CTX = { lang:"ja", navOn:true, mode:"車", dest:"東京駅", remainKm:12.4, etaMin:28, town:"文京区" };
const UTTERANCES = [
  "高速やめて下道で",              // 現行の誤動作ケース
  "この先のコンビニ寄って",
  "あとどれくらい?",
  "やっぱりスカイツリーに変更で",
  "今日はなんか疲れたなあ",
  "ガソリンスタンド探して",
  "静かな曲かけて",
  "俺いつも辛口ラーメン好きなんだよね",   // remember
  "案内やめて",
  "次どっち?",
];

async function callOnce({ withTools, msg }) {
  const body = {
    model: MODEL, temperature: 0.4, max_tokens: 120,
    messages: [
      { role:"system", content: SYS },
      { role:"user", content: `context: ${JSON.stringify(CTX)}\n\nドライバー: ${msg}` },
    ],
  };
  if (withTools) { body.tools = TOOLS; body.tool_choice = "auto"; }
  const t0 = performance.now();
  const r = await fetch(URL, { method:"POST", headers:{ Authorization:`Bearer ${key}`, "Content-Type":"application/json" }, body: JSON.stringify(body) });
  const j = await r.json();
  const ms = performance.now() - t0;
  const ch = j.choices?.[0]?.message || {};
  const tool = ch.tool_calls?.[0]?.function;
  const usage = j.usage || {};
  return { ms, tokIn: usage.prompt_tokens, tokOut: usage.completion_tokens,
    kind: tool ? ("tool:"+tool.name) : "text",
    detail: tool ? tool.arguments : (ch.content||"").slice(0,40) };
}

function stats(a){ const s=[...a].sort((x,y)=>x-y); const p=q=>s[Math.min(s.length-1,Math.floor(q*s.length))]; const mean=s.reduce((x,y)=>x+y,0)/s.length; return { p50:Math.round(p(.5)), p90:Math.round(p(.9)), mean:Math.round(mean), min:Math.round(s[0]), max:Math.round(s[s.length-1]) }; }

async function run(withTools){
  const lat=[], tin=[], tout=[]; const rows=[];
  await callOnce({ withTools, msg:"こんにちは" }); // warmup (discarded)
  for(const msg of UTTERANCES){
    const r = await callOnce({ withTools, msg });
    lat.push(r.ms); tin.push(r.tokIn||0); tout.push(r.tokOut||0);
    rows.push(`  ${String(Math.round(r.ms)).padStart(4)}ms  in${String(r.tokIn).padStart(4)} out${String(r.tokOut||0).padStart(3)}  ${r.kind.padEnd(18)} ${JSON.stringify(msg)} -> ${r.detail}`);
  }
  return { lat:stats(lat), tin:stats(tin), tout:stats(tout), rows };
}

console.log("### BASELINE (plain chat, no tools) ###");
const base = await run(false);
base.rows.forEach(r=>console.log(r));
console.log("latency", base.lat, "| tokIn", base.tin, "| tokOut", base.tout);

console.log("\n### TOOL-CALLING (7 tools, tool_choice=auto) ###");
const tool = await run(true);
tool.rows.forEach(r=>console.log(r));
console.log("latency", tool.lat, "| tokIn", tool.tin, "| tokOut", tool.tout);

console.log("\n### DELTA (tool - baseline) ###");
console.log("p50", tool.lat.p50-base.lat.p50, "ms | p90", tool.lat.p90-base.lat.p90, "ms | mean", tool.lat.mean-base.lat.mean, "ms");
console.log("tokIn +"+(tool.tin.mean-base.tin.mean)+" avg (tool schema overhead)");

