  { type: "function", function: { name: "search_poi", description: "周辺またはルート沿いのPOI（コンビニ・GS・カフェ等）を検索", parameters: { type: "object", properties: { query: { type: "string" }, nearRoute: { type: "boolean", description: "ルート沿いを優先するなら true" } }, required: ["query"] } } },
  { type: "function", function: { name: "control", description: "ナビ操作", parameters: { type: "object", properties: { action: { type: "string", enum: ["start", "stop", "repeat", "mute"] } }, required: ["action"] } } },
  { type: "function", function: { name: "play_music", description: "音楽をかける（気分・状況を mood に短く要約）。消音(mute)とは別物", parameters: { type: "object", properties: { mood: { type: "string" } } } } },
  { type: "function", function: { name: "remember", description: "ドライバーの好み・事実を保存", parameters: { type: "object", properties: { fact: { type: "string" } }, required: ["fact"] } } },
  { type: "function", function: { name: "recall", description: "保存済みの好み・事実を想起", parameters: { type: "object", properties: { topic: { type: "string" } }, required: ["topic"] } } },
] as const;

const ALLOWED_TOOLS = new Set(["navigate", "change_route", "get_status", "search_poi", "control", "play_music", "remember", "recall"]);
const CONTROL_ACTIONS = new Set(["start", "stop", "repeat", "mute"]);
const TOOL_ARG_MAX = 120;

interface NavToolCall {
  tool: string;
  args: Record<string, string | boolean>;
}

function str(value: unknown, max = TOOL_ARG_MAX): string | null {
  if (typeof value !== "string") return null;
  const v = value.trim();
  return v ? v.slice(0, max) : null;
}

/** Validate a model tool call against the allow-list + per-tool arg schema.
 *  Returns a sanitized {tool,args} or null (→ caller falls back to a reply). */
function validateToolCall(name: string, rawArgs: string | undefined): NavToolCall | null {
  if (!ALLOWED_TOOLS.has(name)) return null;
  let a: Record<string, unknown> = {};
  try {
    a = rawArgs ? (JSON.parse(rawArgs) as Record<string, unknown>) : {};
  } catch {
    a = {};
  }
  const args: Record<string, string | boolean> = {};
  switch (name) {
    case "navigate": {
      const dest = str(a.destination);
      if (!dest) return null;
      args.destination = dest;
      if (typeof a.avoidHighways === "boolean") args.avoidHighways = a.avoidHighways;
      return { tool: name, args };
    }
    case "change_route": {
      if (typeof a.avoidHighways === "boolean") args.avoidHighways = a.avoidHighways;
      const wp = str(a.addWaypoint);
      if (wp) args.addWaypoint = wp;
      // 空の change_route は無効（何も変えない呼び出しを弾く）
      return "avoidHighways" in args || "addWaypoint" in args ? { tool: name, args } : null;
    }
    case "get_status":
      return { tool: name, args };
    case "search_poi": {
      const q = str(a.query);
      if (!q) return null;
      args.query = q;
      if (typeof a.nearRoute === "boolean") args.nearRoute = a.nearRoute;
      return { tool: name, args };
    }
    case "control": {
      if (typeof a.action !== "string" || !CONTROL_ACTIONS.has(a.action)) return null;
      args.action = a.action;
      return { tool: name, args };
    }
    case "play_music": {
      const mood = str(a.mood);
      if (mood) args.mood = mood;
      return { tool: name, args };
    }
    case "remember": {
      const fact = str(a.fact, 300);
      if (!fact) return null;
      args.fact = fact;
      return { tool: name, args };
    }
    case "recall": {
      const topic = str(a.topic);
      if (!topic) return null;
      args.topic = topic;
      return { tool: name, args };
    }
    default:
      return null;
  }
}

