     M2 で navChatReply を mode:"tools" へ切り替え、この関数を配線する。 */
function handleToolCall(data){
  const a = (data && data.args) || {};
  switch(data.tool){
    case "navigate":
      // 行き先の新規設定/変更。avoidHighways 指定があれば道種フラグを確定（高速確認を省略）。
      if(typeof a.avoidHighways==="boolean"){ S.avoidHighways=a.avoidHighways; S.avoidTolls=a.avoidHighways; S.pendingRoad=false; }
      a.destination ? searchDestination(a.destination) : botSay(cannedFor("chat"));
      break;
    case "change_route":
      changeRoute(a); break;
    case "get_status":
      speakStatus(); break;                 // テンプレ生成（ETA幻覚防止・2往復禁止）
    case "search_poi":
      a.query ? addWaypointByQuery(a.query) : botSay(cannedFor("chat")); break;
    case "control":
      controlNav(a.action); break;
    case "play_music":
      playMusicStub(a.mood); break;
    case "remember":
      rememberFact(a.fact); break;          // M3でコレクション保存に差し替え
    case "recall":
      recallFact(a.topic); break;           // M3でコレクション想起に差し替え
    default:
      botSay(cannedFor("chat"));
  }
}
// 現在ルートの条件変更（高速回避の切替 / 経由地追加）。ナビは終了させない。
function changeRoute(a){
  if(a.addWaypoint){ addWaypointByQuery(a.addWaypoint); return; }   // 経由地追加（内部でリルート）
  if(typeof a.avoidHighways==="boolean"){
    S.avoidHighways=a.avoidHighways; S.avoidTolls=a.avoidHighways; S.pendingRoad=false;
    if(!S.destination){ botSay(T().needDest); return; }
    botSay(a.avoidHighways ? T().tollAvoid : T().tollUse, false);   // 即時ack（読み上げ）
    buildRoute(()=>botSay(a.avoidHighways ? T().reroutedAvoid : T().reroutedUse));  // 引き直し完了で一言
    return;
  }
  botSay(cannedFor("chat"));
}
