import fs from "fs";

/* ===== A) 第1層 安全アンカーの決定的テスト（voice-nav.html の layer1Safety を複製）===== */
function layer1Safety(t){
  const s=(t||"").trim();
  if(/^(?:(?:ナビ|案内)?\s*を?\s*(?:やめて|やめる|止めて|停止|終了|ストップ|キャンセル)|stop|cancel|end nav|quit)[\s。.．！!]*$/i.test(s)) return "stopNav";
  if(/^(?:ミュート|消音|静かに(?:して)?|しずかに(?:して)?|黙って|mute|quiet|be quiet|shut up)[\s。.．！!]*$/i.test(s)) return "mute";
  if(/^(?:次どっち|次はどっち|次どこ|もう一回|もういちど|もう一度|どっちだっけ|repeat|again|say again)[\s。.．？?！!]*$/i.test(s)) return "repeat";
  return null;
}
const A_CASES = [
  ["案内やめて", "stopNav"],            // ④ 停止
  ["やめて", "stopNav"],
  ["ストップ", "stopNav"],
  ["ナビ停止", "stopNav"],
  ["高速やめて下道で", null],           // ④ これは stop ではない → LLMへ（change_route）
  ["静かに", "mute"],
  ["消音して", "mute"],
  ["次どっち", "repeat"],
  ["この先のコンビニ寄って", null],
  ["東京駅まで", null],
];
console.log("### A) layer1Safety（安全アンカー）###");
let aPass=0;
for(const [txt,exp] of A_CASES){
  const got=layer1Safety(txt);
  const ok=got===exp; if(ok)aPass++;
  console.log(`${ok?"✅":"❌"} ${JSON.stringify(txt).padEnd(24)} → ${String(got).padEnd(8)} (expect ${exp})`);
}
console.log(`A: ${aPass}/${A_CASES.length} pass\n`);

/* ===== B) サーバの tool routing 実測（navChat.ts の実プロンプト/道具を忠実複製）===== */
let key=process.env.OPENAI_API_KEY||"";
if(!key && fs.existsSync(".env")){ const m=fs.readFileSync(".env","utf8").match(/^OPENAI_API_KEY\s*=\s*(.+)$/m); if(m) key=m[1].trim().replace(/^['"]|['"]$/g,""); }
if(!key){ console.log("no key → skip B"); process.exit(aPass===A_CASES.length?0:1); }

const TOOLS_SYSTEM_PROMPT = [
  "あなたはカーナビ「MulmoNavi」の音声アシスタント。運転中のドライバーと話す相棒。",
  "",
  "厳守:",
  "- 返答は必ず context.lang の言語で（ja=日本語 / en=English）。地名も含め言語を混在させない。",
  "- ナビ操作・道種変更・周辺検索・状況確認・音楽・記憶は、文章で答えず必ず対応する道具(tool)を呼ぶ。",
  "- 行き先の“変更/新規設定”は navigate を使う。既存ルートを保ったままの“寄り道/経由地追加”は change_route の addWaypoint を使う。",
  '  例: 「東京駅に変更で」→ navigate(destination:"東京駅") ／ 「セブン寄って」→ change_route(addWaypoint:"セブンイレブン")',
  "- 「高速やめて下道で」等の道種変更は change_route(avoidHighways:true)。ナビは終了させない。",
  "- ETA・残り距離・現在地・走行モードを聞かれたら get_status を呼ぶ（数値を自分で作らない。実際の値はアプリが答える）。",
  "- 音楽リクエスト（かけて/流して等）は play_music を呼ぶ。mute（消音）と混同しない。",
  "- 対応していない要求は道具を無理に呼ばず、短く一言で会話として断る。",
  "- 感情・世間話・雑談は道具を呼ばず会話で返す（2〜3文、共感＋一言）。勝手に目的地化しない。",
  "- 記号・絵文字・括弧・箇条書きは禁止。ナビ会話は短く（日本語約30字/英語約15語）。",
].join("\n");
const NAV_TOOLS = [
  { type:"function", function:{ name:"navigate", description:"目的地を設定してルート検索を開始（行き先の新規設定・変更）", parameters:{ type:"object", properties:{ destination:{type:"string"}, avoidHighways:{type:"boolean"} }, required:["destination"] } } },
  { type:"function", function:{ name:"change_route", description:"現在のルート条件を変更（高速回避の切替、経由地の追加）。ナビは終了しない", parameters:{ type:"object", properties:{ avoidHighways:{type:"boolean"}, addWaypoint:{type:"string"} } } } },
  { type:"function", function:{ name:"get_status", description:"現在地・残距離・ETA・走行モードを取得（数値はアプリが返す）", parameters:{ type:"object", properties:{} } } },
  { type:"function", function:{ name:"search_poi", description:"周辺またはルート沿いのPOI（コンビニ・GS・カフェ等）を検索", parameters:{ type:"object", properties:{ query:{type:"string"}, nearRoute:{type:"boolean"} }, required:["query"] } } },
  { type:"function", function:{ name:"control", description:"ナビ操作", parameters:{ type:"object", properties:{ action:{type:"string", enum:["start","stop","repeat","mute"] } }, required:["action"] } } },
  { type:"function", function:{ name:"play_music", description:"音楽をかける（気分・状況を mood に短く要約）。消音(mute)とは別物", parameters:{ type:"object", properties:{ mood:{type:"string"} } } } },
  { type:"function", function:{ name:"remember", description:"ドライバーの好み・事実を保存", parameters:{ type:"object", properties:{ fact:{type:"string"} }, required:["fact"] } } },
  { type:"function", function:{ name:"recall", description:"保存済みの好み・事実を想起", parameters:{ type:"object", properties:{ topic:{type:"string"} }, required:["topic"] } } },
];
const CTX = { lang:"ja", navOn:true, mode:"車", dest:"東京駅", remainKm:12.4, etaMin:28, town:"文京区" };

async function callTools(msg){
  const r=await fetch("https://api.openai.com/v1/chat/completions",{ method:"POST",
    headers:{ Authorization:`Bearer ${key}`, "Content-Type":"application/json" },
    body: JSON.stringify({ model:"gpt-4o-mini", temperature:0.4, max_tokens:120, tools:NAV_TOOLS, tool_choice:"auto",
      messages:[{role:"system",content:TOOLS_SYSTEM_PROMPT},{role:"user",content:`context: ${JSON.stringify(CTX)}\n\nドライバー: ${msg}`}] }) });
  const j=await r.json(); const m=j.choices?.[0]?.message; const c=m?.tool_calls?.[0]?.function;
  return c ? {tool:c.name, args:c.arguments} : {reply:(m?.content||"").slice(0,40)};
}
const B_CASES = [
  ["高速やめて下道で", "change_route", a=>JSON.parse(a).avoidHighways===true],  // ④ リルート（停止しない）
  ["この先のコンビニ寄って", "search_poi|change_route", null],
  ["あとどれくらい?", "get_status", null],
  ["やっぱりスカイツリーに変更で", "navigate", null],
  ["静かな曲かけて", "play_music", null],   // muteではない
  ["俺いつも辛口ラーメン好きなんだよね", "remember", null],
  ["今日は疲れたなあ", "reply", null],       // 雑談
];
console.log("### B) tool routing（gpt-4o-mini・実プロンプト/道具）###");
let bPass=0;
for(const [msg,expTool,argChk] of B_CASES){
  const res=await callTools(msg);
  const got=res.tool||"reply";
  const toolOk = expTool.split("|").includes(got);
  const argOk = !argChk || (res.tool && argChk(res.args));
  const ok = toolOk && argOk; if(ok)bPass++;
