// 認識結果が「自分のTTSのエコー」か判定（バージイン時に自分の声を拾わないため）
function isEcho(transcript){
  const norm=s=>String(s||"").toLowerCase().replace(/[\s、。,.!！?？「」]/g,"");
  const bot=norm(S._botText), t=norm(transcript);
  if(!bot || !t) return false;
  if(bot.includes(t) || t.includes(bot)) return true;   // 完全/部分一致
  const set=new Set(bot); let common=0; const tset=new Set(t);
  tset.forEach(ch=>{ if(set.has(ch)) common++; });
  return common/Math.max(1,tset.size) > 0.7;   // 文字の重なりが大きい → エコー
}

