// 認識結果が「自分のTTSのエコー」か判定（final=コマンド化を守るための厳しめ判定）。
// 「止まりやすい」側に倒す方針:
//  - 短い発話(<4字)はコマンドの可能性が高いのでエコー扱いしない（例:「止めて」「右」）
//  - 文字重なり率の閾値を 0.7→0.82 に引き上げ（生の声をエコーと誤判定しにくく）
function isEcho(transcript){
  const norm=s=>String(s||"").toLowerCase().replace(/[\s、。,.!！?？「」]/g,"");
  const bot=norm(S._botText), t=norm(transcript);
  if(!bot || !t) return false;
  if(t.length<4) return false;                          // 短い声はエコー扱いしない
  if(bot.includes(t) || t.includes(bot)) return true;   // 完全/部分一致
  const set=new Set(bot); let common=0; const tset=new Set(t);
  tset.forEach(ch=>{ if(set.has(ch)) common++; });
  return common/Math.max(1,tset.size) > 0.82;
}
// 高速バージイン用の“軽い”エコー判定。発話中に interim を拾った瞬間に TTS を止めるため、
// 「明確なエコー（botテキストに完全包含される長め文字列）」だけを弾き、それ以外は
// ユーザーの声とみなして即停止する（＝止まりやすい）。誤爆はログで後調整。
function isEchoLight(transcript){
  const norm=s=>String(s||"").toLowerCase().replace(/[\s、。,.!！?？「」]/g,"");
  const bot=norm(S._botText), t=norm(transcript);
  if(!bot || !t || t.length<4) return false;   // 短い声は止める側（エコー扱いしない）
  return bot.includes(t);                       // botに完全包含される時だけ明確なエコー
}

