async function navChatReply(userText, fallbackType){
  if(!S.navChatToken || !S.navChatUrl){ botSay(cannedFor(fallbackType)); return; }
  // ストリーミング: 応答を文が確定する端からTTS開始（第1文で声が出る）。
  const ctrl=new AbortController();
  S.navAbort=ctrl;                 // バージイン(flushTts)から中断できるよう保持
  const to=setTimeout(()=>ctrl.abort(), NAV_CHAT_TIMEOUT_MS);
  const tReq=performance.now();
  try{
    const res=await fetch(S.navChatUrl,{ method:"POST",
      headers:{ "Authorization":"Bearer "+S.navChatToken, "Content-Type":"application/json" },
      // mode:"tools" + stream:true → SSE ストリーミング経路。
      body: JSON.stringify({ message:userText, mode:"tools", stream:true, context: buildNavContext() }), signal: ctrl.signal });
    if(!res.ok || !res.body) throw new Error("http "+res.status);
    await consumeNavStream(res, tReq, fallbackType);
  }catch(e){
    if(ctrl.signal.aborted) return;   // ユーザー割り込み等 → フォールバックしない
    botSay(cannedFor(fallbackType));   // 不達/失敗 → 定型文
  }finally{
    clearTimeout(to);
    if(S.navAbort===ctrl) S.navAbort=null;
  }
}
// 文末（。．！？.!?改行）で完全な文を切り出す。末尾の未完部分は rest に残す。
function extractSentences(text){
  const re=/[^。．.!！?？\n]*[。．.!！?？\n]/g;
  let m, sentences=[], last=0;
  while((m=re.exec(text))){ sentences.push(m[0]); last=re.lastIndex; }
  return { sentences, rest: text.slice(last) };
}
// SSEを逐次消費：contentデルタは文確定ごとにTTSへ、tool は handleToolCall へ。
async function consumeNavStream(res, tReq, fallbackType){
  const reader=res.body.getReader();
  const dec=new TextDecoder();
  let buf="", spoken="", pending="", bubble=null, spokeAny=false, firstAt=0;
  const speakSentence=(s)=>{
    const t=s.trim(); if(!t) return;
    if(!spokeAny){ spokeAny=true; firstAt=performance.now();
      console.log(`[MulmoNavi] nav-chat stream: 1st sentence @${Math.round(firstAt-tReq)}ms "${t.slice(0,20)}"`); }
    tts(t, { cache:false, el:bubble, sinceRecv:tReq });   // 直列キューに投入（第1文から即再生）
  };
  const onDelta=(text)=>{
    if(!bubble) bubble=addMsg("", "bot");
    pending += text;
    const { sentences, rest }=extractSentences(pending);
    pending=rest;
    for(const s of sentences){ spoken+=s; speakSentence(s); }
    bubble.textContent = spoken + pending;   // 未確定分も画面には表示
    $("log").scrollTop=$("log").scrollHeight;
  };
  while(true){
    const { value, done }=await reader.read();
    if(done) break;
    buf += dec.decode(value, { stream:true });
    const lines=buf.split("\n"); buf=lines.pop()||"";
    for(const line of lines){
      const s=line.trim(); if(!s.startsWith("data:")) continue;
      let ev; try{ ev=JSON.parse(s.slice(5).trim()); }catch{ continue; }
      if(ev.type==="delta"){ onDelta(ev.text||""); }
      else if(ev.type==="tool"){ handleToolCall(ev); }   // 会話バブルは作られない（contentなし）
      else if(ev.type==="error"){ throw new Error("stream error"); }
      // "done" は while 終了で処理
    }
  }
  // 残りの未確定文を読み上げ＆表示
  if(pending.trim()){ spoken+=pending; if(bubble) bubble.textContent=spoken; speakSentence(pending); pending=""; }
  if(!spokeAny && !bubble){ /* toolのみ or 空 → 何もしない */ }
}

// 新しいユーザー発話が来たら、進行中の読み上げを止めてキューを空にする（割り込み）。
// ストリーミング中のnav-chatも中断（第2文以降の生成・再生を止める）。
function flushTts(){ _ttsQueue.length=0; stopSpeaking(); try{ if(S.navAbort) S.navAbort.abort(); }catch(e){} }

