import fs from "fs";
let key=process.env.OPENAI_API_KEY||"";
if(!key && fs.existsSync(".env")){ const m=fs.readFileSync(".env","utf8").match(/^OPENAI_API_KEY\s*=\s*(.+)$/m); if(m) key=m[1].trim().replace(/^['"]|['"]$/g,""); }

const SYS=[
  "あなたはカーナビ「MulmoNavi」の音声アシスタント。運転中のドライバーと話す相棒。",
  "- 返答は日本語。ナビ操作は道具(tool)を呼ぶ。感情・雑談は道具を呼ばず会話で2〜3文。記号禁止。",
].join("\n");
const TOOLS=[
  {type:"function",function:{name:"change_route",description:"ルート条件変更(高速回避/経由地)。ナビ終了しない",parameters:{type:"object",properties:{avoidHighways:{type:"boolean"},addWaypoint:{type:"string"}}}}},
  {type:"function",function:{name:"control",description:"ナビ操作",parameters:{type:"object",properties:{action:{type:"string",enum:["start","stop","repeat","mute"]}},required:["action"]}}},
];
function extractSentences(text){ const re=/[^。．.!！?？\n]*[。．.!！?？\n]/g; let m,s=[],last=0; while((m=re.exec(text))){s.push(m[0]);last=re.lastIndex;} return {sentences:s,rest:text.slice(last)}; }

async function run(msg, withTools){
  const t0=performance.now();
  const r=await fetch("https://api.openai.com/v1/chat/completions",{method:"POST",
    headers:{Authorization:`Bearer ${key}`,"Content-Type":"application/json"},
    body:JSON.stringify({model:"gpt-4o-mini",temperature:0.4,max_tokens:120,stream:true,
      ...(withTools?{tools:TOOLS,tool_choice:"auto"}:{}),
      messages:[{role:"system",content:SYS},{role:"user",content:msg}]})});
  const reader=r.body.getReader(); const dec=new TextDecoder();
  let buf="",pending="",firstSentAt=0,firstTokAt=0,full="",toolName="",toolArgs="";
  while(true){ const {value,done}=await reader.read(); if(done)break;
    buf+=dec.decode(value,{stream:true}); const lines=buf.split("\n"); buf=lines.pop()||"";
    for(const line of lines){ const s=line.trim(); if(!s.startsWith("data:"))continue; const d=s.slice(5).trim();
      if(!d||d==="[DONE]")continue; let j; try{j=JSON.parse(d)}catch{continue}
      const delta=j.choices?.[0]?.delta; if(!delta)continue;
      if(delta.content){ if(!firstTokAt)firstTokAt=performance.now(); full+=delta.content; pending+=delta.content;
        const {sentences,rest}=extractSentences(pending); pending=rest;
        if(sentences.length && !firstSentAt){ firstSentAt=performance.now(); }
      }
      const c=delta.tool_calls?.[0]?.function; if(c){ if(c.name)toolName=c.name; if(c.arguments)toolArgs+=c.arguments; if(!firstTokAt)firstTokAt=performance.now(); }
    }
  }
  const end=performance.now();
  if(toolName){ console.log(`TOOL  "${msg}" → ${toolName}(${toolArgs})  TTFT=${Math.round(firstTokAt-t0)}ms total=${Math.round(end-t0)}ms`); }
  else{ console.log(`CHAT  "${msg}"  TTFT=${Math.round(firstTokAt-t0)}ms  1stSentence=${Math.round(firstSentAt-t0)}ms  total=${Math.round(end-t0)}ms\n      full="${full.slice(0,50)}"`); }
  return {firstSentAt:firstSentAt-t0};
}

console.log("### streaming: 会話（第1文までの時間が肝）###");
const r1=await run("今日はなんか疲れたなあ", true);
const r2=await run("運転しながら聞ける豆知識ある?", true);
console.log("\n### streaming: 道具（tool assembles）###");
await run("高速やめて下道で", true);
await run("案内やめて", true);
console.log("\n=== 判定（TTS ~400ms を足して 1.5s 以内か）===");
for(const [n,r] of [["疲れた",r1],["豆知識",r2]]){
  const est=Math.round(r.firstSentAt)+400;
  console.log(`${n}: 第1文=${Math.round(r.firstSentAt)}ms + TTS~400ms ≈ ${est}ms  ${est<=1500?"✅ ≤1.5s":"⚠ >1.5s"}`);
}

