async function navChatReply(userText, fallbackType){
  if(!S.navChatToken || !S.navChatUrl){ botSay(cannedFor(fallbackType)); return; }
  const ctrl=new AbortController();
  S.navAbort=ctrl;                 // バージイン(flushTts)から中断できるよう保持
  const to=setTimeout(()=>ctrl.abort(), NAV_CHAT_TIMEOUT_MS);
  const tReq=performance.now();
  const post=(extra)=>fetch(S.navChatUrl,{ method:"POST",
    headers:{ "Authorization":"Bearer "+S.navChatToken, "Content-Type":"application/json" },
    body: JSON.stringify(Object.assign({ message:userText, mode:"tools", context: buildNavContext() }, extra)), signal: ctrl.signal });
  try{
    // 1) まずストリーミングを試す（応答を文確定ごとにTTS開始＝第1文で声が出る）。
    let res=await post({ stream:true });
    const ct=(res.headers.get("content-type")||"");
    if(res.ok && res.body && ct.includes("text/event-stream")){
      await consumeNavStream(res, tReq, fallbackType); return;
    }
    // 2) ストリーム不可 → 非ストリーム経路へ堅牢フォールバック
    //    （サーバ未再起動でstreamTools無し / Viteプロキシが SSE を502で落とす 等でもここで動く）
    console.log("[MulmoNavi] stream unavailable (status="+res.status+", ct="+ct+") → non-stream fallback");
    if(!(res.ok && ct.includes("application/json"))) res=await post({});   // 502等なら非streamで取り直し
    if(!res.ok) throw new Error("http "+res.status);
    const data=await res.json();
    const tRecv=performance.now();
    if(data && typeof data.tool==="string"){ handleToolCall(data); return; }
    if(data && typeof data.action==="string"){ handleLLMAction(data); return; }   // 旧経路（防御的）
    if(data && typeof data.reply==="string" && data.reply.trim()){ botSay(data.reply.trim(), true, { cache:false, sinceRecv:tRecv }); return; }
    botSay(cannedFor(fallbackType));
  }catch(e){
    if(ctrl.signal.aborted) return;   // ユーザー割り込み等 → フォールバックしない
    botSay(cannedFor(fallbackType));   // 不達/失敗 → 定型文
  }finally{
    clearTimeout(to);
    if(S.navAbort===ctrl) S.navAbort=null;
  }
}

