function buildRoute(cb){
  if(!S.destination){ botSay(T().needDest); return; }
  if(!S.origin){ S.origin = S.map.getCenter().toJSON(); }
  // 後勝ち世代ガード: 連続でルート条件を変えると DirectionsService のコールバックが
  // 前後することがある。最新世代(mySeq===S.routeSeq)の結果だけを適用・読み上げし、
  // 追い越された古い結果は破棄する（古いリルートが後から上書きする競合を防ぐ）。
  const mySeq = (S.routeSeq = (S.routeSeq||0) + 1);
  const req={
    origin:S.origin, destination:S.destination,
    waypoints:S.waypoints.map(w=>({location:w.loc,stopover:true})),
    travelMode:google.maps.TravelMode[S.travelMode],
    avoidTolls:!!S.avoidTolls,
    avoidHighways:!!S.avoidHighways,
    optimizeWaypoints:false
  };
  S.dirService.route(req,(res,status)=>{
    if(mySeq !== S.routeSeq){   // 追い越された古い結果 → 適用も読み上げもしない
      console.log("[MulmoNavi] stale route dropped (seq "+mySeq+" < "+S.routeSeq+")");
      return;
    }
    if(status==="OK"){
      S.dirRenderer.setDirections(res);
      S.route=res.routes[0];
      const leg = S.route.legs;
      S.steps = leg.flatMap(l=>l.steps);
      S.curStep=0; S.lastSpokenStep=-1;
      const totalDist = leg.reduce((a,l)=>a+l.distance.value,0);
      const totalTime = leg.reduce((a,l)=>a+l.duration.value,0);
      renderSteps();
      if(cb) cb();
      else botSay(T().routeReady(fmtDist(totalDist), fmtDuration(totalTime)));
    }else{
      botSay(T().noRoute);
    }
  });
}

