// （barge-in の「止まりやすさ」は interim 側の isEchoLight で維持しつつ、確認プロンプト等の
//   TTSエコーが final としてコマンド化され確認ループを生むのを防ぐ）。
const ECHO_GUARD_MS = 3500;
async function speakOne(text, opts){
  if(!S.tts) return;
  S._botText = text;   // バージイン用: 今読み上げている文（自分のエコー判定に使う）
  try{
    await speakOneInner(text, opts);
  } finally {
    S._botText = "";
    // 発話“終了”時刻で直近bot発話を記録 → 以後 ECHO_GUARD_MS 窓で遅延エコーを弾く
    if(!S._echoBuf) S._echoBuf=[];
    S._echoBuf.push({ text, at: Date.now() });
    if(S._echoBuf.length>5) S._echoBuf.shift();
  }

// 発話“直後”の遅延エコー判定。speaking=false になった後でも、直近数件の bot 発話
// （ECHO_GUARD_MS 窓内）に一致する認識結果はエコーとみなして破棄する。これで
// 「◯◯を設定しました」「高速使いますか?」等のTTSがコマンド化して確認ループになるのを防ぐ。
function isLateEcho(transcript){
  const buf=S._echoBuf; if(!buf || !buf.length) return false;
  const now=Date.now();
  return buf.some(e => (now-e.at)<ECHO_GUARD_MS && isEcho(transcript, e.text));
}
// 高速バージイン用の“軽い”エコー判定。発話中に interim を拾った瞬間に TTS を止めるため、

