let _restarting=false;
function scheduleRestart(delay){
  clearTimeout(restartTimer);
  restartTimer=setTimeout(()=>{
    restartTimer=null;
    if(!wantListen || listening || _restarting) return;
    _restarting=true;
    // 毎回フレッシュな認識器で再開する。同一 recog を再start するとブラウザは results
    // index を0に戻す一方、二重発火防止用の recog._done は前セッションの値のまま残り、
    // 新しい final が全て "i < _done" で破棄されて無反応になる（割り込み後に多発）。
    try{ killRecog(recog); }catch(e){}
    recog=buildRecog();
    try{ recog.start(); console.log("[MulmoNavi STT] restart (fresh recog)"); }
    catch(e){ console.log("[MulmoNavi STT] restart failed:", e && e.message); _restarting=false; }
  }, delay||300);
}
// 自己修復ウォッチドッグ: ハンズフリー中なのに認識が止まっていたら再武装する
// （onend取りこぼし・start例外・割り込み後の停止などを一定周期で回復し、必ず「聞ける状態」へ戻す）。
setInterval(()=>{
  if(wantListen && !listening && !_restarting){ console.log("[MulmoNavi STT] watchdog → restart"); scheduleRestart(0); }
}, 2500);

