// true=RouteIntent DSL経路（新）／false=差分ツール経路（旧・ロールバック用・残置）。
const USE_INTENT = true;
async function navChatReply(userText, fallbackType){
  if(!S.navChatToken || !S.navChatUrl){ botSay(cannedFor(fallbackType)); return; }
  const ctrl=new AbortController();
  S.navAbort=ctrl;                 // バージイン(flushTts)から中断できるよう保持
  const to=setTimeout(()=>ctrl.abort(), NAV_CHAT_TIMEOUT_MS);
  const tReq=performance.now();
  const post=(extra)=>fetch(S.navChatUrl,{ method:"POST",
    headers:{ "Authorization":"Bearer "+S.navChatToken, "Content-Type":"application/json" },
    body: JSON.stringify(Object.assign({ message:userText, context: buildNavContext() }, extra)), signal: ctrl.signal });
  try{
    if(USE_INTENT){
      console.log("[MulmoNavi] path=intent");
      const res=await post({ mode:"intent" });
      if(!res.ok) throw new Error("http "+res.status);
      const data=await res.json();
      if(data && data.intent){ await applyRouteIntent(data.intent); return; }
      botSay(cannedFor(fallbackType)); return;
    }
    // ── 旧経路（差分ツール／ストリーミング）残置（USE_INTENT=false で有効・ロールバック用）──
    console.log("[MulmoNavi] path=tools");
    let res=await post({ mode:"tools", stream:true });
    const ct=(res.headers.get("content-type")||"");
    if(res.ok && res.body && ct.includes("text/event-stream")){
      await consumeNavStream(res, tReq, fallbackType); return;
    }
    console.log("[MulmoNavi] stream unavailable (status="+res.status+", ct="+ct+") → non-stream fallback");
    if(!(res.ok && ct.includes("application/json"))) res=await post({ mode:"tools" });
    if(!res.ok) throw new Error("http "+res.status);
    const data=await res.json();
    const tRecv=performance.now();
    if(data && typeof data.tool==="string"){ handleToolCall(data); return; }
    if(data && typeof data.action==="string"){ handleLLMAction(data); return; }
    if(data && typeof data.reply==="string" && data.reply.trim()){ botSay(data.reply.trim(), true, { cache:false, sinceRecv:tRecv }); return; }
    botSay(cannedFor(fallbackType));
  }catch(e){
    if(ctrl.signal.aborted) return;   // ユーザー割り込み等 → フォールバックしない
    botSay(cannedFor(fallbackType));   // 不達/失敗 → 定型文
  }finally{
    clearTimeout(to);
    if(S.navAbort===ctrl) S.navAbort=null;
  }
}

/* ============================ RouteIntent DSL エンジン ============================
   nav-chat(mode:"intent")が返す部分的な RouteIntent を、前回状態にマージ→差分判定→
   変化があれば地名解決→buildRoute。未指定は前回値維持（返し漏れ耐性）。 */
function cloneIntent(x){ return { origin:x.origin, destination:x.destination?{query:x.destination.query}:null,
  via:(x.via||[]).map(v=>({query:v.query})), prefer:{avoidHighways:!!x.prefer.avoidHighways, avoidTolls:!!x.prefer.avoidTolls} }; }
// 受信の部分Intentを前回状態にマージ（item3/9: 未指定=維持, via=完全配列, prefer=サブ項目維持）
function mergeIntent(prev, inc){
  inc = inc || {};
  const m = cloneIntent(prev);
  if(inc.origin==="current") m.origin="current";
  else if(inc.origin && typeof inc.origin==="object" && inc.origin.query) m.origin={query:String(inc.origin.query)};
  else if(typeof inc.origin==="string" && inc.origin.trim()) m.origin = (inc.origin==="current"?"current":{query:inc.origin.trim()});
  if(inc.destination && typeof inc.destination==="object" && inc.destination.query) m.destination={query:String(inc.destination.query)};
  else if(typeof inc.destination==="string" && inc.destination.trim()) m.destination={query:inc.destination.trim()};
  if(Array.isArray(inc.via)) m.via = inc.via.map(v=> typeof v==="string"?{query:v}:(v&&v.query?{query:String(v.query)}:null)).filter(Boolean);
  if(inc.prefer && typeof inc.prefer==="object"){
    if(typeof inc.prefer.avoidHighways==="boolean") m.prefer.avoidHighways=inc.prefer.avoidHighways;
    if(typeof inc.prefer.avoidTolls==="boolean") m.prefer.avoidTolls=inc.prefer.avoidTolls;
  }
  return m;
}
function diffIntent(a,b){
  const d=[];
  if(JSON.stringify(a.origin)!==JSON.stringify(b.origin)) d.push("origin");
  if(JSON.stringify(a.destination)!==JSON.stringify(b.destination)) d.push("destination");
  if(JSON.stringify(a.via)!==JSON.stringify(b.via)) d.push("via");
  if(JSON.stringify(a.prefer)!==JSON.stringify(b.prefer)) d.push("prefer");
  return d;
}
// 地名→latlng の共通解決（item4）: textSearch → geocoder フォールバック。先頭候補を採用。
function resolvePlace(query){
  return new Promise((resolve)=>{
    if(!S.places || !query){ resolve(null); return; }
    const req={ query }; if(S.me){ req.location=S.me; req.radius=30000; }
    try{
      S.places.textSearch(req,(res,st)=>{
        if(st===google.maps.places.PlacesServiceStatus.OK && res && res[0] && res[0].geometry && res[0].geometry.location){
          resolve({loc:res[0].geometry.location, name:res[0].name||query}); return;
        }
        if(S.geocoder){ S.geocoder.geocode({address:query},(gr,gs)=>{
          resolve((gs==="OK"&&gr&&gr[0])?{loc:gr[0].geometry.location, name:query}:null);
        }); } else resolve(null);
      });
    }catch(e){ resolve(null); }
  });
}
// マージ後Intentを実状態(S.destination/originOverride/waypoints/prefer)へ解決。gen で後勝ち。
async function resolveIntentToState(m, gen, changedPrefer){
  if(m.origin==="current"){ S.originOverride=null; S.originName=null; }
  else if(m.origin && m.origin.query){
    const r=await resolvePlace(m.origin.query); if(gen!==S.intentSeq) return;
    if(r){ S.originOverride=r.loc; S.originName=r.name; }
  }
  if(m.destination && m.destination.query){
    const r=await resolvePlace(m.destination.query); if(gen!==S.intentSeq) return;
    if(r){ S.destination=r.loc; S.destName=r.name; }
  }
  const via=[];
  for(const v of (m.via||[])){ const r=await resolvePlace(v.query); if(gen!==S.intentSeq) return; if(r) via.push({loc:r.loc, name:r.name}); }
  S.waypoints = via;
  S.avoidHighways=!!m.prefer.avoidHighways; S.avoidTolls=!!m.prefer.avoidTolls;
  if(changedPrefer) S.roadChosen=true;   // 道種は決定済み扱い（以後高速確認しない）
  const isCurrent = (m.origin==="current");
  console.log("[MulmoNavi ORIGIN] resolved", {
    name: isCurrent?"current":(S.originName||null), isCurrent,
    lat: isCurrent?(S.me?S.me.lat:null):(S.originOverride&&S.originOverride.lat&&S.originOverride.lat()),
    lng: isCurrent?(S.me?S.me.lng:null):(S.originOverride&&S.originOverride.lng&&S.originOverride.lng())
  });
}
// 経路要求を適用。未指定維持マージ→差分→（nav変化あれば）解決→buildRoute。後勝ち世代ガード付き。
async function applyRouteIntent(intent){
  const gen = ++S.intentSeq;
  console.log("[MulmoNavi INTENT] received", JSON.stringify(intent||{}), "gen", gen);
  if(!intent || typeof intent!=="object"){ console.log("[MulmoNavi INTENT] invalid → keep prev, noop", gen); return; }
  const prev = S.routeIntent;
  const merged = mergeIntent(prev, intent);
  const diff = diffIntent(prev, merged);
  S.routeIntent = merged;
  console.log("[MulmoNavi INTENT] merged", JSON.stringify(merged), "diff", JSON.stringify(diff), "gen", gen);
  const say = (intent && typeof intent.say==="string") ? intent.say.trim() : "";
  const navChanged = diff.length>0;
  if(!navChanged){
    console.log("[MulmoNavi INTENT] action=noop gen", gen);
    if(say) botSay(say);
    updateOriginUI();
    return;
  }
  try{
    await resolveIntentToState(merged, gen, diff.indexOf("prefer")>=0);
    if(gen!==S.intentSeq){ console.log("[MulmoNavi INTENT] superseded gen", gen); return; }   // item8 後勝ち
    updateOriginUI();
    if(!S.destination){ console.log("[MulmoNavi INTENT] action=noop(no destination) gen", gen); botSay(say||T().needDest); return; }
    console.log("[MulmoNavi INTENT] action=buildRoute gen", gen);
    if(say) botSay(say, true);                 // LLMの一言を即読み上げ
    buildRoute(say ? (function(){}) : undefined);  // say がある時は routeReady と二重にしない
  }catch(e){
    console.log("[MulmoNavi INTENT] resolve error", e&&e.message);
    botSay(say||cannedFor("chat"));
  }
}

