function startNav(){
  if(!S.route && !S.destination){ botSay(T().needDest); return; }
  // item4-3: ナビ開始時は origin を "current" に戻す（現在地からの経路にする）。
  const wasExplicit = !!S.originOverride;
  S.routeIntent.origin="current"; S.originOverride=null; S.originName=null; updateOriginUI();
  console.log("[MulmoNavi ORIGIN] resolved", { name:"current", isCurrent:true, lat:S.me?S.me.lat:null, lng:S.me?S.me.lng:null });
  if(wasExplicit && S.destination){
    // 出発地が明示されていた → 現在地から引き直してからナビ開始
    buildRoute(()=>_startNavLoop());
  }else{
    _startNavLoop();
  }
}
// 実際のナビ開始処理（追従・再計算・到着判定は現在地基準のまま＝従来通り）。
function _startNavLoop(){
  if(!S.route){ botSay(T().needDest); return; }
  S.navOn=true; S.curStep=0; S.lastSpokenStep=-1;
  unlockAudioOnce();           // 「ナビ開始」タップを使って確実に音声を解錠（スマホ対策）
  requestWakeLock();           // 走行中は画面を消さない（スマホを車載時に有効）
  $("banner").classList.add("show");
  S.map.setZoom(18); S.map.setTilt?.(45);
  botSay(T().navStart);
  updateBanner(); speakStep(0, true);
  if(navigator.geolocation){
    S.watchId=navigator.geolocation.watchPosition(onNavPosition,()=>{},
      {enableHighAccuracy:true,timeout:8000,maximumAge:1000});
  }
}
function stopNav(){
  S.navOn=false;
  if(S.watchId!=null){navigator.geolocation.clearWatch(S.watchId);S.watchId=null;}
  releaseWakeLock();
  $("banner").classList.remove("show");
  S.map.setTilt?.(0);
  botSay(T().navStop);
  resetNavState();   // item5: 経路状態を全クリア（次の目的地で高速確認が再度出る＝B-2の副作用解消）
}
// item5: origin/destination/via/prefer/route/roadChosen/pendingRoad をまとめてクリア。
// origin は "current" に戻す（前回の出発地を引き継がない）。stopNav と到着時から呼ぶ。
// フラグ追加時もここに1箇所足すだけでリセット漏れが起きない構造。
function resetNavState(){
  S.routeIntent = { origin:"current", destination:null, via:[], prefer:{avoidHighways:false, avoidTolls:false} };
  S.originOverride=null; S.originName=null;
  S.destination=null; S.destName=""; S.waypoints=[];
  S.avoidHighways=false; S.avoidTolls=false;
  S.route=null; S.roadChosen=false; S.pendingRoad=false;
  updateOriginUI();
  if(typeof renderSteps==="function") renderSteps();
  console.log("[MulmoNavi INTENT] resetNavState (cleared)");
}

