// 「近くの〜/コンビニ/トイレ」等のカテゴリ検索か（＝現在地バイアスが正しいもの）を判定。
function isCategoryQuery(query){
  const s=String(query||"");
  if(/近く|ちかく|周辺|近隣|この先|nearby|nearest|closest|around/i.test(s)) return true;
  for(const c of CATEGORIES){ if(c.re.test(s)) return true; }   // コンビニ/GS/トイレ/カフェ 等
  return false;
}
// 認識結果を {loc,name} に。失敗時は geocoder フォールバック。
function _placeFromResult(res,st,query,resolve){
  if(st===google.maps.places.PlacesServiceStatus.OK && res && res[0] && res[0].geometry && res[0].geometry.location){
    resolve({loc:res[0].geometry.location, name:res[0].name||query}); return;
  }
  if(S.geocoder){ S.geocoder.geocode({address:String(query)},(gr,gs)=>{
    resolve((gs==="OK"&&gr&&gr[0])?{loc:gr[0].geometry.location, name:query}:null);
  }); } else resolve(null);
}
// 地名→latlng の共通解決（origin/destination/via 共通・片方だけ直さない）。
// 問題1修正: 固有名詞（駅名・施設名）は findPlaceFromQuery（locationBias無し＝遠方の駅も正解）。
//            カテゴリ（近くのコンビニ等）は従来の textSearch＋現在地バイアス（既存挙動を維持）。
function resolvePlace(query){
  return new Promise((resolve)=>{
    if(!S.places || !query){ resolve(null); return; }
    try{
      if(isCategoryQuery(query)){
        const req={ query:String(query) }; if(S.me){ req.location=S.me; req.radius=30000; }   // カテゴリ=現在地バイアス
        S.places.textSearch(req,(res,st)=>_placeFromResult(res,st,query,resolve));
      }else{
        // 固有名詞: locationBias を付けずに検索（現在地が遠くても正しい駅/施設を返す）
        S.places.findPlaceFromQuery({ query:String(query), fields:["name","geometry"] },(res,st)=>_placeFromResult(res,st,query,resolve));
      }
    }catch(e){ resolve(null); }
  });
}

