/* ============================ 所要時間の比較（高速あり/なし 2本）============================
   DSL経路(applyRouteIntent)から呼ぶ。avoidHighways:false/true の2本を『並列』で発行し、
   prefer に一致する方を描画・もう一方は数値保持。渋滞込み(duration_in_traffic)を優先。
   片方失敗でも継続（比較できないが動く）。世代は intentGen + pairSeq の二重ガード。 */
function _legDur(leg){ // 渋滞込み優先・無ければ duration
  let t=0, allTraffic=true;
  for(const l of leg){ if(l.duration_in_traffic && l.duration_in_traffic.value!=null) t+=l.duration_in_traffic.value; else { t+=(l.duration&&l.duration.value)||0; allTraffic=false; } }
  return { dur:t, usedTraffic:allTraffic };
}
function routeInfo(res){
  if(!res||!res.routes||!res.routes[0]) return null;
  const leg=res.routes[0].legs;
  const dist=leg.reduce((a,l)=>a+((l.distance&&l.distance.value)||0),0);
  const d=_legDur(leg);
  return { dist, dur:d.dur, usedTraffic:d.usedTraffic, res };
}
function etaClock(sec){ const dt=new Date(Date.now()+sec*1000); return dt.getHours()+":"+String(dt.getMinutes()).padStart(2,"0"); }
function durMin(sec){ return Math.round(sec/60); }
// item8: 片道の1発話で両方の数字を伝える（2往復にしない）。片方のみなら片方だけ。
function announceCompare(iHwy, iLocal, sayFallback){
  const ja=S.lang==="ja"; const parts=[];
  if(iHwy) parts.push(ja? `高速で${durMin(iHwy.dur)}分、${etaClock(iHwy.dur)}着です。` : `Highway ${durMin(iHwy.dur)} min, arriving ${etaClock(iHwy.dur)}.`);
  if(iLocal) parts.push(ja? `下道なら${durMin(iLocal.dur)}分です。` : `Local roads ${durMin(iLocal.dur)} min.`);
  const msg=parts.join(ja?"":" ");
  botSay(msg || sayFallback || T().routeReady(iHwy?fmtDist(iHwy.dist):"", ""), true, {cache:false});
}
// item7: 比較パネル（距離/所要/到着/料金枠）。prefer 側をハイライト。
function updateCompareUI(){
