async function buildRoutePair(intentGen, sayFallback){
  if(!S.destination){ botSay(T().needDest); return; }
  const originLatLng = S.originOverride || (S.me ? {lat:S.me.lat,lng:S.me.lng} : S.map.getCenter().toJSON());
  const pairSeq = (S.routeSeq = (S.routeSeq||0) + 1);   // item2: ペアで共有する世代番号
  const isDriving = (S.travelMode==="DRIVING");
  const baseReq = {
    origin:originLatLng, destination:S.destination,
    waypoints:S.waypoints.map(w=>({location:w.loc,stopover:true})),
    travelMode:google.maps.TravelMode[S.travelMode],
    avoidTolls:!!S.avoidTolls, optimizeWaypoints:false
  };
  if(isDriving) baseReq.drivingOptions={ departureTime:new Date(), trafficModel:"bestguess" };   // item3
  const t0=performance.now();
  // 徒歩は高速/下道の区別が無いので1本のみ（比較UIは出さない）
  const pair = isDriving ? await Promise.all([ _routeOnce(baseReq,false), _routeOnce(baseReq,true) ])
                         : [ await _routeOnce(baseReq,false), null ];
  const latMs=Math.round(performance.now()-t0);
  // item2: 後着Intent/ペアに追い越されていたら破棄（二重ガード）
