  const iHwy=routeInfo(pair[0]), iLocal=routeInfo(pair[1]);
  console.log("[MulmoNavi PAIR] result", { latMs, isDriving,
    hwy: iHwy?{distM:iHwy.dist,durS:iHwy.dur,traffic:iHwy.usedTraffic,src:iHwy.usedTraffic?"duration_in_traffic":"duration"}:null,
    local: iLocal?{distM:iLocal.dist,durS:iLocal.dur,traffic:iLocal.usedTraffic}:null });
  if(!iHwy && !iLocal){ console.log("[MulmoNavi PAIR] both failed"); botSay(T().noRoute); return; }   // item6: 両方失敗のみエラー
  // item5: 描画は prefer.avoidHighways に一致する方（無ければ成功した方）
  const preferLocal=!!S.avoidHighways;
  const chosen = preferLocal ? (iLocal||iHwy) : (iHwy||iLocal);
  try{ S.dirRenderer.setDirections(chosen.res); }catch(e){ console.log("[MulmoNavi PAIR] setDirections threw", e&&e.message); }
  S.route=chosen.res.routes[0];
