// 問題1(保険): LLMのsayに含まれる所要/到着の数字が実測とズレていたら検知ログ（上書きはしない）。
function _etaToMin(s){ const p=String(s).split(":"); return (parseInt(p[0],10)||0)*60+(parseInt(p[1],10)||0); }
function checkSayNumbers(say){
  const c=S.compare;
  if(!say||typeof say!=="string"||!c||!(c.hwy||c.local)) return;   // 実測が無ければ検証不可
  const actualMin=[c.hwy&&durMin(c.hwy.dur), c.local&&durMin(c.local.dur)].filter(v=>typeof v==="number");
  const actualEta=[c.hwy&&etaClock(c.hwy.dur), c.local&&etaClock(c.local.dur)].filter(Boolean);
  const timeRe=/(\d{1,2})[:時](\d{1,2})\s*分?/g; const etas=[]; let m;
  while((m=timeRe.exec(say))) etas.push(parseInt(m[1],10)+":"+String(parseInt(m[2],10)).padStart(2,"0"));
  const dm=say.replace(timeRe,"").match(/(\d{1,3})\s*分/);   // 時刻表現を除いた「◯分」＝所要
  if(dm){ const said=parseInt(dm[1],10);
    if(actualMin.length && !actualMin.some(a=>Math.abs(a-said)<=1))
      console.log("[MulmoNavi SAY] numeric-mismatch", {kind:"min", said, actual:actualMin}); }
  for(const e of etas){ const said=_etaToMin(e);
    if(actualEta.length && !actualEta.some(a=>Math.abs(_etaToMin(a)-said)<=2))
      console.log("[MulmoNavi SAY] numeric-mismatch", {kind:"eta", said:e, actual:actualEta}); }
}

