// 所要/時刻/距離の数値を含むか（時刻 21:21・21時21分／◯分／◯km・◯キロ・◯m）。
function _hasNumericClaim(say){
  return /(\d{1,2})[:時]\d{1,2}\s*分?/.test(say) || /\d{1,3}\s*分/.test(say)
      || /\d+(?:\.\d+)?\s*(?:km|キロメートル|キロ|メートル|m)\b/i.test(say);
}
// 会話履歴の bot 発話から数値(時刻/所要/距離)を伏字化して渡す（問題3: 履歴汚染対策）。
// LLM が過去の「49分」等を「提供された値」と誤認して再利用するのを構造的に断つ。
function _redactNumbers(t){
  return String(t||"")
    .replace(/(\d{1,2})[:時]\d{1,2}\s*分?/g,"（時刻）")
    .replace(/\d{1,3}\s*分/g,"（所要）")
    .replace(/\d+(?:\.\d+)?\s*(?:km|キロメートル|キロ|メートル|m)\b/gi,"（距離）");
}
// 問題1(保険): 実測(compare)がある時、sayの数字が実測とズレていたら検知ログ（上書きはしない）。
function _etaToMin(s){ const p=String(s).split(":"); return (parseInt(p[0],10)||0)*60+(parseInt(p[1],10)||0); }
function checkSayNumbers(say){
  const c=S.compare;
  if(!say||typeof say!=="string"||!c||!(c.hwy||c.local)) return;   // 実測が無ければ検証不可
  const actualMin=[c.hwy&&durMin(c.hwy.dur), c.local&&durMin(c.local.dur)].filter(v=>typeof v==="number");
  const actualEta=[c.hwy&&etaClock(c.hwy.dur), c.local&&etaClock(c.local.dur)].filter(Boolean);
  const timeRe=/(\d{1,2})[:時](\d{1,2})\s*分?/g; const etas=[]; let m;
  while((m=timeRe.exec(say))) etas.push(parseInt(m[1],10)+":"+String(parseInt(m[2],10)).padStart(2,"0"));
  const dm=say.replace(timeRe,"").match(/(\d{1,3})\s*分/);   // 時刻表現を除いた「◯分」＝所要
  if(dm){ const said=parseInt(dm[1],10);
    if(actualMin.length && !actualMin.some(a=>Math.abs(a-said)<=1))
      console.log("[MulmoNavi SAY] numeric-mismatch", {kind:"min", said, actual:actualMin}); }
  for(const e of etas){ const said=_etaToMin(e);
    if(actualEta.length && !actualEta.some(a=>Math.abs(_etaToMin(a)-said)<=2))
      console.log("[MulmoNavi SAY] numeric-mismatch", {kind:"eta", said:e, actual:actualEta}); }
}
// 問題1/2(検知→遮断): 実測が無い(computed:false)のに say が数値を含む＝捏造。
// 安全な文言に差し替えて返す（実測がある時は従来の検知のみで say はそのまま）。
function guardSay(say, willCompute){
  const computed=!!(S.compare && (S.compare.hwy||S.compare.local));
  if(computed){ checkSayNumbers(say); return say; }
  if(say && typeof say==="string" && _hasNumericClaim(say)){
    console.log("[MulmoNavi SAY] fabricated-when-uncomputed", {said:say});
    const ja=S.lang==="ja";
    return willCompute ? (ja?"ルートを調べますね。":"Let me look up the route.")
                       : (ja?"まだ経路を計算していません。目的地を教えてください。":"I haven't calculated the route yet. Where to?");
  }
  return say;
}

// 問題3: bot 発話の数値は伏字化して渡す（過去のETA/所要/距離の再利用を防ぐ）。user はそのまま。
const recent=S.history.slice(0,-1).slice(-6).map(h=> h.role==="bot" ? {bot:_redactNumbers(h.text)} : {[h.role]:h.text});
if(recent.length) ctx.recent=recent;

const data=await res.json();   // 封筒 {intent, actions, say}（後方互換: intent のみでも可）
if(data && (data.intent || data.actions)){
  // 問題1/2: 実測が無いのに数値を含む say は捏造 → 安全文言に差し替え（検知だけでなく遮断）。
  const willCompute=!!(data.intent && data.intent.destination);
  const safeSay=guardSay((data.intent&&data.intent.say)||data.say, willCompute);
  if(data.intent && typeof data.intent.say==="string") data.intent.say=safeSay;
  if(typeof data.say==="string") data.say=safeSay;
  if(data.actions) dispatchActions(data.actions);       // 経路以外（記憶/音楽/削除確認）

