import fs from "fs";
let key=process.env.OPENAI_API_KEY||"";
if(!key && fs.existsSync(".env")){const m=fs.readFileSync(".env","utf8").match(/^OPENAI_API_KEY\s*=\s*(.+)$/m);if(m)key=m[1].trim().replace(/^['"]|['"]$/g,"");}
if(!key){console.log("no key → skip");process.exit(0);}

const BASE=[
"あなたはカーナビ「MulmoNavi」の音声アシスタント。運転中のドライバーの相棒。",
"route_intent ツールを1回だけ呼ぶ。経路と経路以外の行動を同じ呼び出しで返す。",
"- remember: 『覚えて』と言われたら {key,value,kind}。",
"【say】短い一言。say は常に必ず返す。",
"【say はアクションの結果のみ】remember/recall/forget/play_music を実行した時の say は、そのアクションの結果だけを述べる（記憶なら『覚えました』）。経路の数字や別の話題を混ぜない。",
"【数字の厳守】距離・所要・到着は【経路の現在状態】に提供された値だけを使う。無い項目は数字を言わず『まだ計算していません』。推測で数字を作らない。",
"【履歴の数字は信用しない】context.recent の距離・所要・到着の数字は古く伏字化されている場合がある。数字は必ず【経路の現在状態】の値だけを使い履歴の数字を再利用しない。",
].join("\n");
const uncomputed="【経路の現在状態】まだ経路を計算していません。距離・所要時間・到着時刻は言わず『まだ計算していません』と答えること。";
const TOOL={type:"function",function:{name:"route_intent",description:"封筒",parameters:{type:"object",properties:{destination:{type:"string"},remember:{type:"object",properties:{key:{type:"string"},value:{type:"string"},kind:{type:"string"}}},say:{type:"string"}}}}};

// 汚染された履歴（伏字化前=最悪ケース）と、伏字化後の両方で試す
const dirty=[{user:"下道で"},{bot:"下道で49分、21時21分着です"}];
const redacted=[{user:"下道で"},{bot:"下道で（所要）、（時刻）着です"}];

async function ask(recent, msg){
  const ctx=JSON.stringify({lang:"ja",recent});
  const r=await fetch("https://api.openai.com/v1/chat/completions",{method:"POST",
    headers:{Authorization:`Bearer ${key}`,"Content-Type":"application/json"},
    body:JSON.stringify({model:"gpt-4o-mini",temperature:0.3,max_tokens:120,tools:[TOOL],tool_choice:"auto",
      messages:[{role:"system",content:BASE+"\n\n"+uncomputed},{role:"user",content:`走行状況(context): ${ctx}\n\nドライバー: ${msg}`}]})});
  const j=await r.json();const m=j.choices?.[0]?.message;const c=m?.tool_calls?.[0]?.function;
  let say="",args={};try{args=c?JSON.parse(c.arguments):{};say=args.say||m?.content||"";}catch{say=m?.content||"";}
  return {say,hasRemember:!!args.remember, hasNum:/\d/.test(say)};
}
const hasNum=s=>/(\d{1,2})[:時]\d{1,2}|\d{1,3}\s*分|\d+\s*(?:km|キロ|m|メートル)/.test(s);
console.log("(a) 未設定「あと何分?」(汚染履歴):");
let a=await ask(dirty,"あと何分?");console.log("   say=",a.say,"→",hasNum(a.say)?"⚠数字あり":"✅数字なし");
console.log("(b) gen3再現「下道が好きって覚えておいて」(汚染履歴・伏字前):");
let b=await ask(dirty,"下道が好きって覚えておいて");console.log("   say=",b.say," remember=",b.hasRemember,"→",hasNum(b.say)?"⚠経路数字あり":"✅経路数字なし");
console.log("(b') 同上（伏字化後の履歴＝実際に送られる形）:");
